import type { ChipProps } from "./chip.types";

import React, {
  forwardRef,
  useCallback,
  useState,
  useEffect,
  createContext,
  useContext,
} from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Clear as ClearIcon } from "@exp-textura/icons";

import { ChipClasses, StyledChip } from "./chip.styles";

interface ChipContextValue {
  handleClose: () => void;
  type: ChipProps["type"];
}

const ChipContext = createContext<ChipContextValue | null>(null);

const useChipContext = () => {
  const context = useContext(ChipContext);
  if (!context) {
    throw new Error("Chip compound components cannot be rendered outside the Chip component");
  }
  return context;
};

const ChipRoot = forwardRef<HTMLSpanElement, ChipProps>(
  (
    {
      className,
      variant = "default",
      type = "subtle",
      size = "default",
      onClose,
      show: showProp = true,
      isOverflow = false,
      hasStartAdornment = false,
      children,
      ...props
    }: ChipProps,
    ref: React.ForwardedRef<HTMLSpanElement>,
  ) => {
    const theme = useTheme();
    const [show, setShow] = useState(showProp);
    const rootClasses = clsx(
      ChipClasses.root,
      {
        [ChipClasses.sm]: size === "sm",
        [ChipClasses.outline]: type === "outline",
        [ChipClasses.overflow]: isOverflow,
        [ChipClasses.hasStartAdornment]: hasStartAdornment,
      },
      className,
    );

    const handleClose = useCallback(() => {
      setShow(false);
      onClose?.();
    }, [onClose]);

    useEffect(() => {
      setShow(showProp);
      if (!showProp) {
        onClose?.();
      }
    }, [onClose, showProp]);

    if (!show) return null;

    const contextValue: ChipContextValue = {
      handleClose,
      type,
    };

    return (
      <ChipContext.Provider value={contextValue}>
        <StyledChip
          ref={ref}
          className={rootClasses}
          currentTheme={theme}
          role={isOverflow ? "button" : undefined}
          tabIndex={isOverflow ? 0 : undefined}
          variant={variant}
          {...props}
        >
          {children}
        </StyledChip>
      </ChipContext.Provider>
    );
  },
);

ChipRoot.displayName = "Chip";

const CloseButton: React.FC<React.HTMLAttributes<HTMLSpanElement>> = ({
  children,
  className,
  onClick,
  "aria-label": customAriaLabel,
  ...props
}) => {
  const { handleClose, type } = useChipContext();
  const buttonClasses = clsx(
    ChipClasses.closeButton,
    {
      [ChipClasses.closeButtonOutline]: type === "outline",
    },
    className,
  );

  const commonProps = {
    "aria-label": customAriaLabel || "close current chip",
    role: "button",
    onClick: (e: React.MouseEvent<HTMLSpanElement, MouseEvent>) => {
      onClick?.(e);
      handleClose();
    },
    tabIndex: 0,
    onKeyDown: (e: React.KeyboardEvent) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        handleClose();
      }
    },
  };

  if (children && React.isValidElement(children)) {
    return React.cloneElement(children as React.ReactElement, {
      className: buttonClasses,
      ...commonProps,
      ...props,
      "aria-hidden": false,
    });
  }

  return (
    <span className={buttonClasses} {...commonProps} {...props}>
      <ClearIcon />
    </span>
  );
};
CloseButton.displayName = "Chip.CloseButton";

const Chip = Object.assign(ChipRoot, {
  CloseButton,
});

export default Chip;
